appearances.css:
.r{display:grid;grid-auto-flow:row dense;grid-template-columns:repeat(12,minmax(0,1fr));gap:3px 0;font-size:10px;line-height:1.2;padding:0 0 2px}
.r>*{grid-column:1/-1}
textarea{min-height:34px;padding:3px 5px;font-size:11px}
select,button{padding:2px 4px;font-size:10px;border-radius:3px}
.row{gap:3px 8px;margin:1px 0}
.row label{gap:3px;font-size:10px}
.sec:has(+ .syl),.sec:has(+ canvas){display:none}
.syl{margin:1px 0;padding:3px;gap:2px;max-height:64px}
.stat{margin:0;font-size:10px}
.sec{border-top:0;margin:3px 0 0;padding:0;font-size:8px;letter-spacing:.14em}
.grid{grid-template-columns:repeat(6,minmax(0,1fr));gap:2px 0;padding:3px 2px 4px;border:1px solid var(--line);border-radius:3px;align-content:start}
.r>:nth-child(12),.r>:nth-child(13){grid-column:1/7}
.r>:nth-child(14),.r>:nth-child(15){grid-column:7/13}
.r>:nth-child(13),.r>:nth-child(15){grid-template-columns:repeat(3,minmax(0,1fr))}
.k{grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;min-height:0}
.k label{order:3;font-size:7.5px;letter-spacing:-.02em;text-align:center;max-width:100%;line-height:1.1;white-space:normal;overflow:visible;text-overflow:clip;text-transform:none}
.k output{order:2;font-size:8px;text-align:center;line-height:1.1;color:var(--muted)}
.k .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.k .kn svg{width:100%;height:100%}
canvas{height:44px!important;margin-top:2px;border-radius:3px}
